begin;
select no_plan();
do $$ declare s uuid; owner_id uuid:=gen_random_uuid(); worker_id uuid:=gen_random_uuid(); begin
 insert into auth.users(id) values(owner_id),(worker_id);
 insert into public.stores default values returning id into s;
 insert into public.staff(user_id,store_id,display_name,role) values(owner_id,s,'Owner','owner'),(worker_id,s,'Worker','staff');
 perform public.seed_store_settings(s,'Tools verification');
 perform set_config('tools.owner',owner_id::text,true);perform set_config('tools.worker',worker_id::text,true);perform set_config('tools.store',s::text,true);
 insert into public.sku_ledger(sku,store_id,issued_at) values('94001',s,now());
 insert into public.units(sku,store_id,title,brand,state,qty_on_hand,received_at,updated_at) values('94001',s,'Acme toaster','Acme','available',3,now(),now());
end $$;
select set_config('request.jwt.claim.sub',current_setting('tools.owner'),true);
select set_config('request.jwt.claim.role','authenticated',true);
select lives_ok($$select public.portal_save_withdrawal(null,'safe',1234,current_date,'person_payout','fixture',current_setting('tools.worker')::uuid,current_setting('tools.owner')::uuid)$$,'record withdrawal through existing RPC');
select is((select (b->>'expected_cents')::int from jsonb_array_elements(public.portal_withdrawal_reconciliation()) b where b->>'source'='safe'),-1234,'expected safe balance subtracts exact withdrawal cents');
select is((select count(*)::int from public.portal_payout_payments where store_id=current_setting('tools.store')::uuid),1,'one linked payout created');
select is((select amount_cents from public.portal_payout_payments where store_id=current_setting('tools.store')::uuid),1234,'linked payout has exact amount');
select lives_ok($$select public.portal_save_withdrawal((select id from public.store_cash_movements where store_id=current_setting('tools.store')::uuid),'safe',2000,current_date,'person_payout','edited',current_setting('tools.worker')::uuid,current_setting('tools.owner')::uuid)$$,'edit existing withdrawal');
select is((select count(*)::int from public.portal_payout_payments where store_id=current_setting('tools.store')::uuid),1,'editing never duplicates linked payout');
select is((select amount_cents from public.portal_payout_payments where store_id=current_setting('tools.store')::uuid),2000,'linked payout follows edit');
select lives_ok($$select public.portal_void_withdrawal((select id from public.store_cash_movements where store_id=current_setting('tools.store')::uuid),'safe')$$,'void withdrawal through original RPC');
select is((select (b->>'expected_cents')::int from jsonb_array_elements(public.portal_withdrawal_reconciliation()) b where b->>'source'='safe'),0,'void restores reconciliation');
select ok((select voided_at is not null from public.portal_payout_payments where store_id=current_setting('tools.store')::uuid),'linked payout void retained for audit');
select throws_ok($$select public.portal_save_withdrawal(null,'safe',-1,current_date,'other','fixture',null,null)$$,'22023',null,'negative withdrawal rejected');
select lives_ok($$select public.portal_set_bay(14,array[3,3,3,0])$$,'create bay with no-bin large-item row');
select is((select row_bins from public.store_bays where store_id=current_setting('tools.store')::uuid and bay_no=14),array[3,3,3,0],'row layout persists');
select lives_ok($$select public.portal_set_bay(15,array[5,5,5,5,5])$$,'allow five rows with five bins each');
select is((select count(*)::int from public.store_locations where store_id=current_setting('tools.store')::uuid and bay_no=15),25,'create all 25 locations for a five-by-five bay');
select lives_ok($$select public.portal_set_bay(16,array[5])$$,'allow a one-row bay');
select is((select count(*)::int from public.store_locations where store_id=current_setting('tools.store')::uuid and bay_no=16),5,'create five bins in a one-row bay');
select lives_ok($$select public.portal_set_bay(17,array[2,0])$$,'allow a two-row bay with a large-item row');
select is((select count(*)::int from public.store_locations where store_id=current_setting('tools.store')::uuid and bay_no=17),3,'create bins and the large-item slot in a two-row bay');
select throws_ok($$select public.portal_set_bay(16,array[6,3,3])$$,'22023','row_bins_must_be_zero_through_five','reject more than five bins per row');
select throws_ok($$select public.portal_set_bay(16,array[3,3,3,3,3,3])$$,'22023','bay_layout_invalid','reject more than five rows');
select throws_ok($$select public.portal_set_bay(18,array[]::int[])$$,'22023','bay_layout_invalid','reject a bay with no rows');
select lives_ok($$select public.portal_move_location_stock('94001','14-1-1',2,null)$$,'put away two unassigned units');
select throws_ok($$select public.portal_move_location_stock('94001','14-1-2',3,'14-1-1')$$,'P0001','not_enough_stock_at_source','cannot exceed stock at source');
select throws_ok($$select public.portal_move_location_stock('94001','14-1-2',2,null)$$,'P0001','not_enough_unassigned_stock','cannot exceed unassigned stock');
select throws_ok($$select public.portal_move_location_stock('94001','14-1-2',1,'14-2-1')$$,'P0001','not_enough_stock_at_source','cannot move from incorrect source');
select lives_ok($$select public.portal_move_location_stock('94001','14-1-2',1,'14-1-1')$$,'move from verified source');
select is((select sum(quantity)::int from public.unit_location_stock where store_id=current_setting('tools.store')::uuid),2,'move conserves assigned quantity');
select is((select qty_on_hand from public.units where store_id=current_setting('tools.store')::uuid and sku='94001'),3,'movement never changes total inventory quantity');
select * from finish();
rollback;
